import contextlib
import io

from qiskit import QuantumCircuit
from qiskit.transpiler import CouplingMap, generate_preset_pass_manager
from qiskit.providers.fake_provider import GenericBackendV2

# the displayed code, verbatim (print captured to check the comment)
backend = GenericBackendV2(num_qubits=5, seed=42)
pm = generate_preset_pass_manager(backend=backend, optimization_level=2)
buf = io.StringIO()
with contextlib.redirect_stdout(buf):
    print(pm.stages)
printed = buf.getvalue().strip()
assert printed == "('init', 'layout', 'routing', 'translation', 'optimization', 'scheduling')", printed


def pass_names(stage_pm):
    out = []

    def walk(task):
        if hasattr(task, "tasks"):
            for sub in task.tasks:
                walk(sub)
        else:
            out.append(type(task).__name__)

    for task in stage_pm.to_flow_controller().tasks:
        walk(task)
    return out


stages = {s: pass_names(getattr(pm, s)) for s in pm.stages if getattr(pm, s) is not None}
routing = stages["routing"]
claims = {
    "A": "SabreLayout",
    "B": "VF2Layout",
    "C": "ConsolidateBlocks",
    "D": "SabreSwap",
    "E": "BasisTranslator",
    "F": "Optimize1qGatesDecomposition",
}
flags = {k: (v in routing) for k, v in claims.items()}
evidence = {}
for k, cls in claims.items():
    where = sorted(s for s, names in stages.items() if cls in names) or ["no preset stage"]
    evidence[k] = (
        f"the routing stage of the level-2 preset contains {routing}; "
        f"`{cls}` is found in stage(s) {where} -> match={flags[k]}"
    )
# Runtime subtlety recorded for the explanation: on a 5-qubit line, a circuit that needs
# routing gets its SWAPs from SabreLayout (layout stage); the routing stage's SabreSwap is skipped.
line_pm = generate_preset_pass_manager(
    backend=GenericBackendV2(num_qubits=5, coupling_map=CouplingMap.from_line(5), seed=42),
    optimization_level=2, seed_transpiler=1)
needs_routing = QuantumCircuit(5)
for a in range(5):
    for b in range(5):
        if a != b:
            needs_routing.cx(a, b)
ran, first_swap = [], []
def cb(**kw):
    name = type(kw["pass_"]).__name__
    ran.append(name)
    if not first_swap and kw["dag"].count_ops().get("swap", 0):
        first_swap.append(name)
line_pm.run(needs_routing, callback=cb)
emit_verdict({
    "answer": sorted(k for k, v in flags.items() if v),
    "evidence": evidence,
    "observed": {"stages": stages, "printed_stages": printed,
                 "line_run_first_swap_inserted_by": first_swap[0] if first_swap else None,
                 "line_run_sabreswap_executed": "SabreSwap" in ran},
})
